import csv
import io


def parse_customers(text: str) -> list[dict[str, str]]:
    """Parse customer CSV text with id, name, and email columns."""
    if text.startswith("\ufeff"):
        text = text[1:]

    reader = csv.reader(io.StringIO(text, newline=""), strict=True)
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("CSV is missing the required header") from None
